-- Nội dung bài học ban đầu Sơn Trà Số (không chứa tài khoản hay mật khẩu)
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (0, 'Chỉnh điện thoại cho dễ sử dụng', 1, 'Mục tiêu: Giúp người lớn tuổi cầm và sử dụng điện thoại thông minh thoải mái, chữ to rõ ràng.

1. Tăng cỡ chữ: Vào Cài đặt (biểu tượng bánh răng) -> Màn hình -> Cỡ chữ và độ phóng to -> Kéo thanh trượt sang phải để chữ to nhất vừa mắt.
2. Bật âm lượng chuông: Vào Cài đặt -> Âm thanh và rung -> Kéo chuông báo và cuộc gọi lên mức dễ nghe.
3. Khóa xoay màn hình: Vuốt từ mép trên màn hình xuống, chạm vào biểu tượng \'Tự động xoay\' để cố định màn hình dọc, tránh bị xoay ngang khi nằm đọc.
4. Giữ màn hình sáng lâu hơn: Đặt thời gian sáng màn hình thành 1 phút hoặc 2 phút để không bị tắt khi đang đọc tin.', '{"question":"Khi muốn làm chữ trên điện thoại to hơn để đọc rõ, bác nên vào mục nào trong Cài đặt?","options":["Mục Màn hình -> Cỡ chữ và thu phóng","Mục Âm thanh và rung","Mục Pin và thiết bị","Mục Bluetooth và kết nối"],"correctChoice":0,"explanation":"Vào Cài đặt -> Màn hình -> Cỡ chữ và thu phóng để phóng to chữ theo ý muốn mà không ảnh hưởng ứng dụng khác."}', 'Bác hãy thử mở phần Cài đặt và kéo cỡ chữ to hơn một nấc ngay trên máy của mình.', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', 'url', NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (1, 'Kết nối mạng Wifi và bật dữ liệu di động 4G', 1, 'Mục tiêu: Đảm bảo điện thoại luôn có mạng Internet khi ở nhà cũng như khi đi ra ngoài.

1. Kết nối Wifi tại nhà: Vuốt từ trên xuống -> Giữ ngón tay vào biểu tượng Wifi -> Chọn tên Wifi nhà mình -> Nhập mật khẩu chính xác.
2. Bật dữ liệu 4G khi ra đường: Vuốt từ trên xuống -> Chạm vào biểu tượng \'Dữ liệu di động\' (hình hai mũi tên ngược nhau) để bật màu xanh.
3. Lưu ý an toàn: Không kết nối vào các mạng Wifi công cộng không có mật khẩu ở nơi vắng người để phòng tránh đánh cắp thông tin.', '{"question":"Khi đi ra ngoài đường hoặc ra chợ An Hải Bắc mà không có Wifi, bác cần bật nút nào để đọc tin tức?","options":["Bật Chế độ máy bay","Bật Dữ liệu di động (4G\\/LTE)","Bật Đèn pin","Bật Không làm phiền"],"correctChoice":1,"explanation":"Dữ liệu di động (4G) sử dụng sóng viễn thông của SIM, giúp bác vào mạng ở mọi nơi."}', 'Hãy nhờ tình nguyện viên kiểm tra xem điện thoại của bác đã bật dữ liệu 4G chưa.', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (2, 'Tra cứu thông tin chính thức trên Cổng thông tin Sơn Trà', 2, 'Mục tiêu: Biết cách vào trang chính thống của phường Sơn Trà để đọc thông báo chỉ đạo và lịch làm việc.

1. Địa chỉ chính thức: https://sontra.danang.gov.vn (luôn có đuôi .gov.vn - trang của nhà nước).
2. Những mục quan trọng: Tin hoạt động của Đảng ủy - UBND phường, Lịch tiếp công dân, Hướng dẫn thủ tục hành chính, Cảnh báo thời tiết - triều cường biển Sơn Trà.
3. Tra cứu kết quả hồ sơ: Nhập mã số biên nhận vào ô Tra cứu trên cổng để biết hồ sơ đất đai, tư pháp đã xong chưa.', '{"question":"Trang thông tin điện tử chính thức của phường Sơn Trà có đuôi tên miền là gì?","options":["sontra.danang.gov.vn","sontradanang.com","ubndsontra.net","tintucsontra.org"],"correctChoice":0,"explanation":"Các cơ quan hành chính nhà nước Việt Nam luôn sử dụng tên miền có đuôi .gov.vn."}', 'Bác hãy lưu trang sontra.danang.gov.vn vào dấu trang (bookmark) của trình duyệt.', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (3, 'Phản ánh kiến nghị qua Tổng đài 1022 Đà Nẵng', 2, 'Mục tiêu: Người dân chủ động gửi ý kiến về trật tự đô thị, đèn đường hỏng, rác thải tại phường mình.

1. Gọi điện thoại: Bấm số 1022 hoặc (0236) 1022 để gặp trực tiếp điện thoại viên.
2. Sử dụng ứng dụng Danang Smart City: Chụp ảnh hiện trường (ví dụ hố ga hỏng ở đường Ngô Quyền) -> Nhập nội dung phản ánh -> Gửi trực tiếp tới cơ quan xử lý.
3. Theo dõi tiến độ: Hệ thống gửi mã tin nhắn, cơ quan phường Sơn Trà sẽ trả lời bằng văn bản kèm ảnh khắc phục trong 2-3 ngày.', '{"question":"Khi phát hiện sự cố đèn chiếu sáng công cộng hoặc ngập úng trên địa bàn phường, bà con gọi số nào?","options":["Gọi Tổng đài dịch vụ công 1022 Đà Nẵng","Gọi số quảng cáo trên cột điện","Đăng bài tự do lên Facebook cá nhân","Chờ họp tổ dân phố cuối năm"],"correctChoice":0,"explanation":"Tổng đài 1022 tiếp nhận và điều phối mọi kiến nghị của người dân Đà Nẵng 24\\/7."}', 'Lưu số 0236 1022 vào danh bạ với tên "Tổng đài 1022 Đà Nẵng".', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (4, 'Giao tiếp bằng Zalo an toàn trong tổ dân phố', 3, 'Mục tiêu: Nhận thông báo tổ dân phố kịp thời, trò chuyện với gia đình mà không bị quấy rối.

1. Tham gia nhóm Zalo tổ dân phố: Nhờ đồng chí tổ trưởng hoặc bí thư chi bộ duyệt vào nhóm.
2. Cài đặt bảo vệ quyền riêng tư: Vào Cài đặt Zalo -> Quyền riêng tư -> Tắt \'Cho phép người lạ tìm thấy qua số điện thoại\' và \'Nhận tin nhắn từ người lạ\'.
3. Tuyệt đối không chuyển tiếp các tin đồn nhảm chưa được cơ quan chức năng kiểm chứng.', '{"question":"Để tránh bị người lạ quấy rầy hoặc lừa đảo qua Zalo, bác nên làm gì?","options":["Tắt tính năng nhận tin nhắn từ người lạ trong phần Quyền riêng tư","Cung cấp mật khẩu Zalo cho bất kỳ ai hỏi","Bấm vào mọi đường dẫn người lạ gửi qua tin nhắn","Chấp nhận kết bạn với tất cả tài khoản lạ"],"correctChoice":0,"explanation":"Chặn tin nhắn từ người lạ giúp tài khoản Zalo chỉ nhận liên lạc từ bạn bè và người quen."}', 'Mở ứng dụng Zalo, kiểm tra phần Quyền riêng tư và tắt mục "Nhận cuộc gọi từ người lạ".', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (5, 'Quét mã QR thanh toán không dùng tiền mặt tại chợ dân sinh', 4, 'Mục tiêu: Tự tin mua hàng tại các sạp chợ Sơn Trà, chợ Mân Thái, chợ Phước Mỹ bằng cách quét mã QR.

1. Mở ứng dụng ngân hàng hoặc ví điện tử (Viettel Money, VNPT Money, MoMo).
2. Chọn biểu tượng Quét mã QR (thường ở góc trên cùng hoặc chính giữa phía dưới màn hình).
3. Hướng camera vào bảng mã QR của tiểu thương: Màn hình sẽ hiện đúng tên người nhận.
4. Nhập chính xác số tiền cần trả -> Nhấn Tiếp tục -> Kiểm tra lại tên sạp hàng -> Xác thực bằng vân tay hoặc mã PIN.
5. Đưa màn hình \'Thanh toán thành công\' cho tiểu thương xem.', '{"question":"Sau khi quét mã QR của tiểu thương bán hoa quả ở chợ, bước quan trọng nhất trước khi bấm Chuyển tiền là gì?","options":["Kiểm tra tên chủ tài khoản và số tiền hiển thị trên màn hình","Tắt điện thoại ngay lập tức","Đọc mật khẩu tài khoản ngân hàng to cho mọi người cùng nghe","Xóa ứng dụng ngân hàng đi"],"correctChoice":0,"explanation":"Luôn nhìn kỹ tên người nhận và số tiền để tránh chuyển nhầm sạp hàng hoặc thừa số 0."}', 'Hãy nhờ tình nguyện viên hỗ trợ thực hành quét mã QR thử nghiệm với số tiền 1.000 đồng.', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (6, 'Thanh toán tiền điện, nước định kỳ qua điện thoại', 4, 'Mục tiêu: Không cần ra điểm thu tiền nước, tiền điện hàng tháng trong những ngày nắng nóng.

1. Chuẩn bị mã khách hàng: Xem trên hóa đơn giấy cũ (ví dụ mã điện lực bắt đầu bằng PD..., mã nước bắt đầu bằng số danh bạ).
2. Mở ứng dụng ngân hàng -> Chọn mục \'Thanh toán hóa đơn\' -> Chọn \'Tiền điện\' hoặc \'Tiền nước\'.
3. Nhập mã khách hàng -> Hệ thống tự động báo số tiền cần nộp tháng này.
4. Bật tính năng \'Trích nợ tự động\' nếu muốn hệ thống tự thanh toán vào ngày 15 hàng tháng.', '{"question":"Mã khách hàng để đóng tiền điện tiền nước được tìm thấy ở đâu dễ nhất?","options":["Trên tờ hóa đơn tiền điện\\/nước cũ hoặc tin nhắn SMS của công ty điện lực\\/cấp nước","Bác tự nghĩ ra một dãy số bất kỳ","Hỏi người lạ trên đường","Nhập số căn cước công dân"],"correctChoice":0,"explanation":"Mỗi hộ gia đình có một mã khách hàng cố định in trên hóa đơn hàng tháng."}', 'Tìm hóa đơn điện tháng trước và ghi lại mã số khách hàng vào sổ tay.', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (7, 'Nhận diện cuộc gọi giả danh cơ quan công an, tòa án', 5, 'Mục tiêu: Tuyệt đối không bị kẻ xấu hù dọa chiếm đoạt tài sản qua điện thoại.

1. Dấu hiệu lừa đảo: Kẻ lạ tự xưng công an, viện kiểm sát, cán bộ phường Sơn Trà thông báo bác liên quan đến đường dây rửa tiền, ma túy hoặc nợ cước điện thoại.
2. Yêu cầu chuyển tiền vào \'tài khoản an toàn\' để điều tra -> 100% LÀ LỪA ĐẢO.
3. NGUYÊN TẮC VÀNG: Cơ quan công an và nhà nước KHÔNG BAO GIỜ làm việc qua điện thoại và KHÔNG BAO GIỜ yêu cầu người dân chuyển tiền.
4. Cách xử lý: Tắt máy ngay lập tức, thông báo cho con cháu hoặc ra thẳng trụ sở công an phường gần nhất để báo cáo.', '{"question":"Nếu có người gọi điện tự xưng là cán bộ công an yêu cầu bác chuyển tiền vào một tài khoản để xác minh, bác cần làm gì?","options":["Cúp máy ngay lập tức, không chuyển tiền và báo cho người nhà hoặc công an phường","Ra ngay ngân hàng rút tiền tiết kiệm để chuyển cho họ","Cung cấp mật khẩu và mã OTP ngân hàng cho họ","Làm theo mọi lời đe dọa của người gọi"],"correctChoice":0,"explanation":"Cơ quan pháp luật Việt Nam luôn gửi giấy mời hoặc giấy triệu tập trực tiếp, không bao giờ yêu cầu chuyển tiền qua điện thoại."}', 'Chia sẻ ngay bài học này cho người thân cùng xóm để đề cao cảnh giác.', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT IGNORE INTO lessons (lesson_no, title, group_no, body, quiz_json, next_step, video_url, video_type, video_filename, audio_url, audio_type, audio_filename, hidden, created_at, updated_at) VALUES (8, 'Bảo vệ mã OTP và tuyệt đối không bấm vào đường link lạ', 5, 'Mục tiêu: Giữ an toàn tuyệt đối cho tài khoản ngân hàng và thông tin cá nhân.

1. Mã OTP (Mật khẩu một lần) là chìa khóa mở két sắt tiền của bác: Không chia sẻ mã OTP cho bất kỳ ai, kể cả người tự xưng là nhân viên ngân hàng.
2. Tin nhắn rác có đường link: Tin nhắn thông báo trúng thưởng, quà tặng kèm đường link lạ -> KHÔNG BẤM VÀO.
3. Nếu lỡ bấm vào link: Thoát ngay trình duyệt, không nhập mật khẩu hay số điện thoại, lập tức gọi điện thoại cho ngân hàng yêu cầu khóa thẻ khẩn cấp.', '{"question":"Khi nhận được tin nhắn báo có mã OTP gửi về máy, bác được phép đọc mã này cho ai?","options":["Tuyệt đối không đọc cho bất kỳ ai (kể cả người tự xưng là nhân viên ngân hàng)","Đọc cho người xưng là cán bộ công nghệ thông tin","Đọc cho người xưng là gọi điện tặng quà","Đọc cho người lạ gọi đến hỏi thăm"],"correctChoice":0,"explanation":"Mã OTP là lớp bảo mật cuối cùng để chuyển tiền. Chia sẻ mã OTP đồng nghĩa với việc đưa tiền cho kẻ gian."}', 'Kiểm tra hộp thư tin nhắn và xóa ngay các tin nhắn lạ chứa liên kết khả nghi.', NULL, NULL, NULL, NULL, NULL, NULL, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
